{
  "operacion": "leer",
  "herramienta": "mind",
  "descripcion": "Lee un archivo de texto UTF-8 (hasta 1 MiB) de una carpeta autorizada y devuelve el contenido y su versión (necesaria para modificar). También extrae el texto de documentos de oficina (.docx, .xlsx, .pptx, .odt, .ods, .odp; hasta 16 MiB), solo para leer. Requiere \"leer\".",
  "parametros": {
    "type": "object",
    "properties": {
      "carpeta": {
        "type": "string",
        "description": "Id de la carpeta autorizada (lo devuelve \"estado\") o su ruta absoluta registrada. Opcional si solo hay una carpeta."
      },
      "ruta": {
        "type": "string",
        "description": "Ruta relativa dentro de la carpeta, con \"/\" entre componentes (por ejemplo \"notas/idea.md\")."
      },
      "desde_linea": {
        "type": "integer",
        "minimum": 1,
        "description": "Primera línea a mostrar (opcional)."
      },
      "lineas": {
        "type": "integer",
        "minimum": 1,
        "description": "Número de líneas a mostrar (opcional)."
      }
    },
    "required": [
      "ruta"
    ],
    "additionalProperties": false
  },
  "anotaciones": {
    "readOnlyHint": true,
    "openWorldHint": false
  }
}
